import json
S={
"om":{"country":"Oman","src":{"label":"Oman Customs (Directorate General of Customs) — veterinary permit to import dogs and cats","url":"https://customs.gov.om/en/business-services/permit/veterinary-permit-to-import-dogs-and-cats"},
"head":"A prior veterinary permit is required, with a rabies antibody blood test and a banned-breed list for dogs.",
"lines":["Oman Customs says a prior veterinary permit must be obtained through the Bayan system before the pet arrives, at a fee of OMR 20. It is normally approved within two hours on any day of the week.","The permit file needs the immunisation record since birth, a photo of the pet, the microchip number, and a rabies antibody blood test from an accredited laboratory. The pet must be over four months old, vaccinated against rabies after 12 weeks of age and within the last 12 months, with blood drawn 21 to 30 days after the last vaccine and the result dated 3 to 12 months before export.","Under Resolution 222/2019 dogs of listed breeds are barred, among them Pit Bull, Staffordshire Terrier, American Bully, Rottweiler, Doberman, Boxer, Great Dane and Japanese Tosa, and mixes of them. On arrival you present the permit, the exporting country's government health certificate, the passport or vaccination record and the lab certificate."]},
"kr":{"country":"South Korea","src":{"label":"USDA APHIS — pet travel from the United States to Korea (relaying Korean quarantine rules)","url":"https://www.aphis.usda.gov/pet-travel/us-to-another-country-export/pet-travel-us-korea"},
"head":"Korea expects a microchip, a current rabies vaccine and a rabies antibody test of 0.5 IU/ml or more.",
"lines":["The US agriculture department page on Korean entry rules says a dog or cat needs a current rabies vaccine given before arrival, a rabies neutralising antibody test of 0.5 IU/ml or higher, and an ISO-compliant microchip. Pets under 90 days old need neither the vaccine nor the test.","From the US the health certificate must be issued by an accredited vet and endorsed within 30 days of export. If the chip or the antibody test could not be done before shipping, they can be done after arrival in Korea, but the animal will likely be held in quarantine at the owner's expense until they are finished.","This is a US-side relay, not the Korean quarantine agency page, so check the Korean agency before travel."]},
"jo":{"country":"Jordan","src":{"label":"Australian Department of Agriculture (Micor) — Jordan dogs, based on Jordan Ministry of Agriculture advice of 27 November 2025","url":"https://micor.agriculture.gov.au/live-animals/jordan/dogs"},
"head":"Jordan told Australia it no longer issues import permits for pet cats and dogs.",
"lines":["The Australian agriculture department says the Jordanian Ministry of Agriculture advised it on 27 November 2025 that import permits for pet cats and dogs will no longer be issued.","The animal must still travel with a veterinary health certificate stating it is free of rabies and has been vaccinated against rabies, and only two pets of each species (cats and dogs) are allowed per traveller.","The page directs questions to the Jordanian Ministry of Agriculture at Agri@moa.gov.jo. This is Australian guidance, so confirm with the ministry before travel."]}}
for k,v in S.items(): json.dump(v,open('dup_work/petspecs/%s.json'%k,'w',encoding='utf8'),ensure_ascii=False,separators=(',',':'))
